import copy
import json
import pathlib
import subprocess
import sys
import tempfile
import unittest

import sbom_diff

REPO = pathlib.Path(__file__).resolve().parents[4]


def current_sbom():
    """The real MiniDAQ SBOM, generated by tools/make_sbom.py."""
    out = subprocess.run([sys.executable, str(REPO / "tools/make_sbom.py"), str(REPO)],
                         capture_output=True, text=True, check=True, env={"SOURCE_DATE_EPOCH": "0"}).stdout
    return json.loads(out)


def find(bom, name):
    return next(c for c in bom["components"] if c["name"] == name)


class SbomDiff(unittest.TestCase):
    def setUp(self):
        self.old = current_sbom()
        self.new = copy.deepcopy(self.old)

    def test_identical_sboms_have_no_changes(self):
        self.assertEqual(sbom_diff.diff(self.old, self.new), [])

    def test_upgrade_is_a_version_change_not_add_and_remove(self):
        c = find(self.new, "nlohmann-json")
        c["version"], c["bom-ref"] = "3.12.0", "nlohmann/nlohmann-json@3.12.0"
        self.assertEqual(sbom_diff.diff(self.old, self.new),
                         [("version", "nlohmann/nlohmann-json", "3.11.3 -> 3.12.0")])

    def test_license_scope_and_hash_changes(self):
        find(self.new, "benchmark")["licenses"] = [{"license": {"id": "MIT"}}]
        find(self.new, "googletest")["scope"] = "required"
        find(self.new, "nlohmann-json")["hashes"][0]["content"] = "0" * 64
        kinds = [(k, n) for k, n, _ in sbom_diff.diff(self.old, self.new)]
        self.assertEqual(kinds, [("hash", "nlohmann/nlohmann-json"), ("license", "google/benchmark"),
                                 ("scope", "google/googletest")])

    def test_added_and_removed(self):
        self.new["components"] = [c for c in self.new["components"] if c["name"] != "benchmark"]
        self.new["components"].append({"type": "library", "group": "fmtlib", "name": "fmt", "version": "11.0.2"})
        self.assertEqual(sbom_diff.diff(self.old, self.new),
                         [("added", "fmtlib/fmt", "11.0.2"), ("removed", "google/benchmark", "1.9.1")])

    def test_exit_status(self):
        with tempfile.TemporaryDirectory() as d:
            a, b = pathlib.Path(d) / "a.json", pathlib.Path(d) / "b.json"
            a.write_text(json.dumps(self.old))
            b.write_text(json.dumps(self.old))
            self.assertEqual(sbom_diff.main(["sbom_diff.py", str(a), str(b)]), 0)
            find(self.new, "googletest")["version"] = "1.16.0"
            b.write_text(json.dumps(self.new))
            self.assertEqual(sbom_diff.main(["sbom_diff.py", str(a), str(b)]), 1)

if __name__ == "__main__":
    unittest.main()
